-- ── story 4-3b: a consignee's own minimum remaining shelf life ─────────────
-- Generated by drizzle-kit (the six column statements) and hand-amended
-- around the generated part: the fail-fast guard, `IF NOT EXISTS` on every
-- column and an existence guard on every constraint (so the body after the
-- guard is re-runnable), the nine CHECKs and the post-migration probe
-- (drizzle-kit is blind to CHECKs; `bun run db:generate` afterwards reports
-- "No schema changes").
--
-- `partner_client_links` (one row per partner × client × role — small):
--   * `min_shelf_life_days integer NULL` — 1..3650 IST days;
--   * `min_shelf_life_percent smallint NULL` — 1..100 percent of each SKU's
--     total shelf life (`skus.shelf_life_days`);
--   both optional, every one set must hold (decision 3), and only a
--   `consignee` link may carry them (`…_shelf_life_consignee_only`). The three
--   CHECKs are added VALID: the scan over a small master table is trivial.
--   `CONSIGNEE_MIN_SHELF_LIFE_DAYS_MIN/MAX` and `…_PERCENT_MIN/MAX`
--   (src/shared/primitives/batch-allocation.ts) mirror them; pinned by
--   test/consignee-shelf-life.spec.ts.
--
-- `picklist_lines` (large — every wave writes it):
--   * `consignee_partner_id uuid`, `consignee_min_shelf_life_days integer`
--     (the consignee's EFFECTIVE minimum in days), `consignee_min_shelf_life_percent
--     smallint` (display) — the consignee rule a line was planned under,
--     FROZEN (decision 6). All NULL when no rule applied; an existing line
--     stays NULL (no consignee rule — the pre-4-3b draw);
--   * `shortfall_cause text` — why an `unfulfillable` slice was left short
--     (A6: `consignee-shelf-life | consignee-unjudgeable`, `SHORTFALL_CAUSES`),
--     NULL = no stock at all;
--   * the five CHECKs are NOT VALID (guide §3): a VALID add would scan the
--     table under the ADD COLUMN's ACCESS EXCLUSIVE lock. NOT VALID enforces
--     every insert and update from here on, and every existing row is NULL in
--     all four columns by construction, which every CHECK admits. No VALIDATE
--     here (the migrator runs the pending set in one transaction) — a PENDING
--     (deploy) entry instead.
--     - the two ranges (1–3650, 1–100);
--     - `picklist_lines_consignee_pairing`: the partner is NULL exactly when
--       both minimums are NULL. The UNJUDGEABLE shape (A3) — partner and
--       percent set, days NULL — is admitted;
--     - `picklist_lines_consignee_needs_rule` (A4): a consignee line always
--       carries its allocation rule (4-3a's column);
--     - `picklist_lines_shortfall_cause_check` (A6): value-only, not coupled
--       to status (a wave cancel moving the line to `cancelled` still passes).
--   `IS NULL OR` comes first on every nullable arm (guide §3).
--
-- No backfill and no index (nothing named that word appears in any DO block —
-- guide §3).
--
-- Lock cost: each ALTER TABLE takes a brief ACCESS EXCLUSIVE lock (no rewrite,
-- no scan on `picklist_lines`). The deploy migrator sets `lock_timeout` on its
-- connection (MIGRATE_LOCK_TIMEOUT_MS, default 5 s): on a timeout the whole
-- pending set rolls back and the remedy is to re-run the deploy (DEPLOY.md §5).
--
-- Rolling deploy (A16): an old (4-3a) api task that generates a wave during
-- the deploy window ignores saved consignee rules — accepted for one window;
-- regenerate any wave generated during it.

-- ── 0. fail-fast: already applied ────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'partner_client_links' AND column_name = 'min_shelf_life_days'
	) THEN
		RAISE EXCEPTION 'migration 0111: partner_client_links.min_shelf_life_days already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "partner_client_links" ADD COLUMN IF NOT EXISTS "min_shelf_life_days" integer;--> statement-breakpoint
ALTER TABLE "partner_client_links" ADD COLUMN IF NOT EXISTS "min_shelf_life_percent" smallint;--> statement-breakpoint
ALTER TABLE "picklist_lines" ADD COLUMN IF NOT EXISTS "consignee_partner_id" uuid;--> statement-breakpoint
ALTER TABLE "picklist_lines" ADD COLUMN IF NOT EXISTS "consignee_min_shelf_life_days" integer;--> statement-breakpoint
ALTER TABLE "picklist_lines" ADD COLUMN IF NOT EXISTS "consignee_min_shelf_life_percent" smallint;--> statement-breakpoint
ALTER TABLE "picklist_lines" ADD COLUMN IF NOT EXISTS "shortfall_cause" text;--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only) ────────────────────────
-- Each ADD is guarded by its name in pg_constraint, so a re-run of the body
-- adds nothing twice.
DO $$
BEGIN
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.partner_client_links'::regclass AND conname = 'partner_client_links_min_shelf_life_days_range') THEN
		ALTER TABLE "partner_client_links" ADD CONSTRAINT "partner_client_links_min_shelf_life_days_range" CHECK (
			"min_shelf_life_days" IS NULL OR "min_shelf_life_days" BETWEEN 1 AND 3650
		);
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.partner_client_links'::regclass AND conname = 'partner_client_links_min_shelf_life_percent_range') THEN
		ALTER TABLE "partner_client_links" ADD CONSTRAINT "partner_client_links_min_shelf_life_percent_range" CHECK (
			"min_shelf_life_percent" IS NULL OR "min_shelf_life_percent" BETWEEN 1 AND 100
		);
	END IF;
	-- Only a consignee link carries a shelf-life rule (decision 1).
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.partner_client_links'::regclass AND conname = 'partner_client_links_shelf_life_consignee_only') THEN
		ALTER TABLE "partner_client_links" ADD CONSTRAINT "partner_client_links_shelf_life_consignee_only" CHECK (
			("min_shelf_life_days" IS NULL AND "min_shelf_life_percent" IS NULL) OR "role" = 'consignee'
		);
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.picklist_lines'::regclass AND conname = 'picklist_lines_consignee_min_shelf_life_days_range') THEN
		ALTER TABLE "picklist_lines" ADD CONSTRAINT "picklist_lines_consignee_min_shelf_life_days_range" CHECK (
			"consignee_min_shelf_life_days" IS NULL OR "consignee_min_shelf_life_days" BETWEEN 1 AND 3650
		) NOT VALID;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.picklist_lines'::regclass AND conname = 'picklist_lines_consignee_min_shelf_life_percent_range') THEN
		ALTER TABLE "picklist_lines" ADD CONSTRAINT "picklist_lines_consignee_min_shelf_life_percent_range" CHECK (
			"consignee_min_shelf_life_percent" IS NULL OR "consignee_min_shelf_life_percent" BETWEEN 1 AND 100
		) NOT VALID;
	END IF;
	-- The partner is NULL exactly when both minimums are (the unjudgeable
	-- shape — partner + percent, days NULL — is admitted, A3).
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.picklist_lines'::regclass AND conname = 'picklist_lines_consignee_pairing') THEN
		ALTER TABLE "picklist_lines" ADD CONSTRAINT "picklist_lines_consignee_pairing" CHECK (
			("consignee_partner_id" IS NULL) = ("consignee_min_shelf_life_days" IS NULL AND "consignee_min_shelf_life_percent" IS NULL)
		) NOT VALID;
	END IF;
	-- A4 — a consignee line always carries its allocation rule.
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.picklist_lines'::regclass AND conname = 'picklist_lines_consignee_needs_rule') THEN
		ALTER TABLE "picklist_lines" ADD CONSTRAINT "picklist_lines_consignee_needs_rule" CHECK (
			"consignee_partner_id" IS NULL OR "allocation_rule" IS NOT NULL
		) NOT VALID;
	END IF;
	-- A6 — value-only (never coupled to status).
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.picklist_lines'::regclass AND conname = 'picklist_lines_shortfall_cause_check') THEN
		ALTER TABLE "picklist_lines" ADD CONSTRAINT "picklist_lines_shortfall_cause_check" CHECK (
			"shortfall_cause" IS NULL OR "shortfall_cause" IN ('consignee-shelf-life','consignee-unjudgeable')
		) NOT VALID;
	END IF;
END $$;
--> statement-breakpoint
-- ── the post-migration assertion (the 0094 model) ─────────────────────────
-- Made-up uuids. (a) The five picklist_lines CHECKs are NOT VALID, the three
-- partner_client_links CHECKs VALID. (b) Every existing link and line reads
-- NULL in the new columns. (c) Every accepted shape inserts — the unjudgeable
-- line included — and is rolled back by a sentinel exception, so a CHECK that
-- refused everything fails the migration. (d) Each refused shape runs in its
-- own subtransaction and must be refused BY ITS NAMED CONSTRAINT (Postgres
-- evaluates CHECKs in name order; each probe violates only its target).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
	n int;
BEGIN
	-- (a)
	SELECT count(*) INTO n
	  FROM pg_constraint
	 WHERE conrelid = 'public.picklist_lines'::regclass
	   AND conname IN ('picklist_lines_consignee_min_shelf_life_days_range', 'picklist_lines_consignee_min_shelf_life_percent_range',
	                   'picklist_lines_consignee_pairing', 'picklist_lines_consignee_needs_rule', 'picklist_lines_shortfall_cause_check')
	   AND contype = 'c'
	   AND NOT convalidated;
	IF n <> 5 THEN
		RAISE EXCEPTION 'migration 0111: expected the five picklist_lines CHECKs present and NOT VALID, found % so.', n;
	END IF;
	SELECT count(*) INTO n
	  FROM pg_constraint
	 WHERE conrelid = 'public.partner_client_links'::regclass
	   AND conname IN ('partner_client_links_min_shelf_life_days_range', 'partner_client_links_min_shelf_life_percent_range',
	                   'partner_client_links_shelf_life_consignee_only')
	   AND contype = 'c'
	   AND convalidated;
	IF n <> 3 THEN
		RAISE EXCEPTION 'migration 0111: expected the three partner_client_links CHECKs present and VALID, found % so.', n;
	END IF;
	-- (b)
	SELECT count(*) INTO n FROM "partner_client_links"
	 WHERE "min_shelf_life_days" IS NOT NULL OR "min_shelf_life_percent" IS NOT NULL;
	IF n <> 0 THEN
		RAISE EXCEPTION 'migration 0111: % existing link(s) carry a shelf-life rule.', n;
	END IF;
	SELECT count(*) INTO n FROM "picklist_lines"
	 WHERE "consignee_partner_id" IS NOT NULL OR "consignee_min_shelf_life_days" IS NOT NULL
	    OR "consignee_min_shelf_life_percent" IS NOT NULL OR "shortfall_cause" IS NOT NULL;
	IF n <> 0 THEN
		RAISE EXCEPTION 'migration 0111: % existing line(s) carry a consignee rule or a shortfall cause.', n;
	END IF;
	-- (c)
	BEGIN
		INSERT INTO "partner_client_links" ("id","tenant_id","partner_id","client_id","role","min_shelf_life_days","min_shelf_life_percent")
		VALUES
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'consignee', 1, NULL),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'consignee', 3650, 100),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'consignee', NULL, 1),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'consignee', NULL, NULL),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'vendor', NULL, NULL);
		INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","shortfall_qty","slice_seq","walk_seq","status","allocation_rule","consignee_partner_id","consignee_min_shelf_life_days","consignee_min_shelf_life_percent","shortfall_cause")
		VALUES
			-- no consignee rule (every pre-4-3b line)
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 0, 'planned', NULL, NULL, NULL, NULL, NULL),
			-- days only, at both bounds
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 0, 'planned', 'fefo', gen_random_uuid(), 1, NULL, NULL),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 0, 'planned', 'fifo', gen_random_uuid(), 3650, 100, NULL),
			-- the UNJUDGEABLE shape (A3): partner + percent, days NULL — an unfulfillable slice with its cause
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), NULL, 0, 1000, 0, 0, 'unfulfillable', 'fefo', gen_random_uuid(), NULL, 1, 'consignee-unjudgeable'),
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), NULL, 0, 1000, 0, 0, 'unfulfillable', 'fefo', gen_random_uuid(), 120, NULL, 'consignee-shelf-life'),
			-- value-only: a cancelled line keeps its cause
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), NULL, 0, 1000, 0, 0, 'cancelled', 'fefo', gen_random_uuid(), 120, NULL, 'consignee-shelf-life');
		RAISE EXCEPTION USING ERRCODE = 'P0111', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0111: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0111' THEN
			NULL;
	END;
	-- (d)
	FOREACH probe IN ARRAY ARRAY[
		'link days 0', 'link days 3651', 'link percent 0', 'link percent 101', 'link vendor rule',
		'line days 0', 'line days 3651', 'line percent 0', 'line percent 101',
		'line partner without minimum', 'line minimum without partner', 'line no rule', 'line cause'
	] LOOP
		refused_by := NULL;
		expected := CASE
			WHEN probe IN ('link days 0', 'link days 3651') THEN 'partner_client_links_min_shelf_life_days_range'
			WHEN probe IN ('link percent 0', 'link percent 101') THEN 'partner_client_links_min_shelf_life_percent_range'
			WHEN probe = 'link vendor rule' THEN 'partner_client_links_shelf_life_consignee_only'
			WHEN probe IN ('line days 0', 'line days 3651') THEN 'picklist_lines_consignee_min_shelf_life_days_range'
			WHEN probe IN ('line percent 0', 'line percent 101') THEN 'picklist_lines_consignee_min_shelf_life_percent_range'
			WHEN probe IN ('line partner without minimum', 'line minimum without partner') THEN 'picklist_lines_consignee_pairing'
			WHEN probe = 'line no rule' THEN 'picklist_lines_consignee_needs_rule'
			ELSE 'picklist_lines_shortfall_cause_check'
		END;
		BEGIN
			CASE probe
				WHEN 'link days 0' THEN
					INSERT INTO "partner_client_links" ("id","tenant_id","partner_id","client_id","role","min_shelf_life_days") VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'consignee', 0);
				WHEN 'link days 3651' THEN
					INSERT INTO "partner_client_links" ("id","tenant_id","partner_id","client_id","role","min_shelf_life_days") VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'consignee', 3651);
				WHEN 'link percent 0' THEN
					INSERT INTO "partner_client_links" ("id","tenant_id","partner_id","client_id","role","min_shelf_life_percent") VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'consignee', 0);
				WHEN 'link percent 101' THEN
					INSERT INTO "partner_client_links" ("id","tenant_id","partner_id","client_id","role","min_shelf_life_percent") VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'consignee', 101);
				WHEN 'link vendor rule' THEN
					INSERT INTO "partner_client_links" ("id","tenant_id","partner_id","client_id","role","min_shelf_life_days") VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'vendor', 90);
				WHEN 'line days 0' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","consignee_partner_id","consignee_min_shelf_life_days")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', gen_random_uuid(), 0);
				WHEN 'line days 3651' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","consignee_partner_id","consignee_min_shelf_life_days")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', gen_random_uuid(), 3651);
				WHEN 'line percent 0' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","consignee_partner_id","consignee_min_shelf_life_days","consignee_min_shelf_life_percent")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', gen_random_uuid(), 10, 0);
				WHEN 'line percent 101' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","consignee_partner_id","consignee_min_shelf_life_days","consignee_min_shelf_life_percent")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', gen_random_uuid(), 10, 101);
				WHEN 'line partner without minimum' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","consignee_partner_id")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', gen_random_uuid());
				WHEN 'line minimum without partner' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","consignee_min_shelf_life_days")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'fefo', 90);
				WHEN 'line no rule' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","allocation_rule","consignee_partner_id","consignee_min_shelf_life_days")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, NULL, gen_random_uuid(), 90);
				WHEN 'line cause' THEN
					INSERT INTO "picklist_lines" ("id","tenant_id","picklist_id","wave_id","order_id","order_line_id","sku_id","bin_id","qty","slice_seq","walk_seq","shortfall_cause")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), gen_random_uuid(), 1000, 0, 0, 'no-stock');
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0111: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "partner_client_links" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "picklist_lines" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0111: a probe row survived.';
	END IF;
END $$;
